import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const wolfFangCard='a2-p10-r3c1';
export const wolfFangScenarios=['wolf-fang-ordinary', 'wolf-fang-owner-ordinary', 'wolf-fang-low', 'wolf-fang-dedicated', 'wolf-fang-far', 'wolf-fang-same-faction', 'wolf-fang-water', 'wolf-fang-metal', 'wolf-fang-lower', 'wolf-fang-maai-one-ordinary', 'wolf-fang-maai-one-dedicated', 'wolf-fang-maai-two-dedicated', 'wolf-fang-evade-ordinary', 'wolf-fang-evade-dedicated', 'wolf-fang-fate', 'wolf-fang-suppressed', 'wolf-fang-silenced', 'wolf-fang-stopped', 'wolf-fang-wrong-owner', 'wolf-fang-decline', 'wolf-fang-noncounter', 'wolf-fang-reroll-ordinary', 'wolf-fang-reroll-dedicated'] as const;
export type WolfFangScenario=typeof wolfFangScenarios[number];
export function isWolfFangScenario(name:string):name is WolfFangScenario{return (wolfFangScenarios as readonly string[]).includes(name);}
export function wolfFangMode(name:WolfFangScenario){const suffix=name.replace('wolf-fang-',''),dedicated=!suffix.includes('ordinary')&&!['low','decline'].includes(suffix),owner=dedicated&&suffix!=='wrong-owner'||suffix==='owner-ordinary',follower=suffix==='water'?'a2-p23-r1c1':suffix==='metal'?'a2-p22-r1c1':suffix==='lower'?'a2-p19-r1c3':null,maai=suffix.startsWith('maai'),evade=suffix.startsWith('evade'),cancel=suffix==='fate',decline=suffix==='decline',reroll=suffix.startsWith('reroll');return {suffix,dedicated,owner,follower,maai,evade,cancel,decline,reroll};}
export function makeWolfFangPhysical(name:WolfFangScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;warrior?:number;spirit?:number}={}){
 const m=wolfFangMode(name),prior=['suppressed','stopped','silenced'].includes(m.suffix),incoming=m.suffix==='noncounter';let s=createGame(players,entropy(),{startingSeat:prior?3:incoming?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.owner?'餓狼ヨーツルム':'侍大将のシン','黒騎士ガーウィン',m.suffix==='same-faction'?'魔導王ガイナス':'小人のランバ','聖騎士ランスロット'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?options.spirit??6:p.id===b?11:6)-gameStats(s,p.id).spirit;}
 s.players[a]!.permanent!.warrior_level!+=(options.warrior??(m.suffix==='low'?4:m.dedicated?0:5))-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,wolfFangCard),takeCard(s,a,'a2-p24-r1c3'),takeCard(s,d,'a2-p02-r2c3'),takeCard(s,d,'a2-p02-r1c3')];if(m.follower)keep.push(takeCard(s,b,m.follower));if(m.suffix==='same-faction')keep.push(takeCard(s,a,'a2-p24-r2c1'));if(m.maai)keep.push(takeCard(s,b,'a2-p06-r1c3'),takeCard(s,b,'a2-p06-r2c1'));if(m.evade)keep.push(takeCard(s,b,'a2-p05-r3c1'));if(incoming)keep.push(takeCard(s,b,'a2-p24-r1c2'));if(prior)keep.push(takeCard(s,d,m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`WOLF_FANG_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('WOLF_FANG_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('WOLF_FANG_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<600;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('WOLF_FANG_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if(m.follower&&id===b)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:m.follower});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));if(options.beforeStart)return s;
 if(prior){act(d,{type:'START_TURN'});settle();act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();}
 const starter=incoming?b:a;act(starter,{type:'START_TURN'});settle(prior?6:1);if(s.phase==='draw')act(starter,{type:'CHOOSE_DRAW',draw:false});if(incoming){act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let n=0;n<400;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('WOLF_FANG_FIXTURE_COUNTER_LIMIT');}
 if(!['far','stopped'].includes(m.suffix)){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c3',targetId:b});settle();}if(m.suffix==='same-faction'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r2c1',targetId:c});settle();act(c,{type:'REVEAL_CHARACTER'});settle();}return s;
}
